function buildDirectionMenuClass() {
  const Base = foundry.applications?.api?.ApplicationV2 ?? FormApplication;
  return class DirectionSettingsMenu extends Base {
    render() {
      openDirectionEditor();
      return this;
    }
  };
}

function openDirectionEditor() {
  if (!game.user.isGM) {
    throw new MusicError("Only the GM can edit the music direction.",
      "Type /music direction to see what it currently says.");
  }
  DirectionEditorClass ??= buildDirectionEditorClass();
  directionEditor ??= new DirectionEditorClass();
  // Reopening starts from what is saved, rather than from an abandoned edit.
  if (!directionEditor.rendered) directionEditor.text = null;
  return directionEditor.render(true);
}

/* --------------------------------------------------------------- commands */

const COMMAND_HELP =
  `<p><b>/music &lt;what is happening&gt;</b> — adapt the soundtrack.<br>` +
  `<b>/music raw &lt;style&gt;</b> — skip the AI rewrite.<br>` +
  `<b>/music status</b> — what is playing.<br>` +
  `<b>/music widget</b> — a small on-screen readout of the same thing (<b>on</b>/<b>off</b>).<br>` +
  `<b>/music diagnose</b> — check every reason it might not be working.<br>` +
  `<b>/music play</b> / <b>pause</b> — for the table if you are the GM, else for you.<br>` +
  `<b>/music on</b> / <b>off</b> — your own playback only.<br>` +
  `<b>/music sync</b> — jump to the live edge.<br>` +
  `<b>/music volume 0.4</b> — your own volume.<br>` +
  `<b>/music morph 3</b> — cross-fade seconds.<br>` +
  `<b>/music temp 1.2</b> / <b>cfg 3</b> / <b>topk 40</b> — generation knobs.<br>` +
  `<b>/music llm on|off</b> — prompt rewriting.<br>` +
  `<b>/music preset &lt;name&gt;</b> — play a saved preset.<br>` +
  `<b>/music presets</b> — list them. <b>/music presets edit</b> — add, test and adjust them (GM).<br>` +
  `<b>/music preset save &lt;name&gt;</b> — keep what is playing now as a preset (GM).<br>` +
  `<b>/music direction</b> — the standing rules the AI follows. ` +
  `<b>/music direction &lt;rule&gt;</b> to set them, <b>clear</b> to remove them, ` +
  `<b>edit</b> for the editor (GM).</p>`;

const COMMANDS = ["help", "status", "widget", "diagnose", "play", "pause", "stop",
  "resume", "on", "off", "sync", "preset", "presets", "direction", "volume",
  "morph", "temp", "topk", "cfg", "llm", "raw"];

const KNOB_EXAMPLES = { morph: "3", temp: "1.2", topk: "40", cfg: "3" };

/**
 * Is `word` one edit away from `command` -- one insertion, deletion,
 * substitution, or a swap of two neighbours?
 *
 * Deliberately strict. At two edits "synth" starts looking like "sync" and a
 * legitimate one-word scene description gets refused, which is a worse failure
 * than letting a genuine typo through to the music model.
 */
function isOneEditApart(word, command) {
  if (word === command) return false;
  const [a, b] = word.length >= command.length ? [word, command] : [command, word];
  if (a.length - b.length > 1) return false;

  let i = 0;
  while (i < b.length && a[i] === b[i]) i++;
  let j = 0;
  while (j < b.length - i && a[a.length - 1 - j] === b[b.length - 1 - j]) j++;

  // Same length: one substitution leaves nothing between the matching ends,
  // and one transposition leaves exactly the two swapped characters.
  if (a.length === b.length) {
    const middle = a.length - i - j;
    if (middle <= 1) return true;
    return middle === 2 && a[i] === b[i + 1] && a[i + 1] === b[i];
  }
  // Different lengths: one insertion, so the ends must meet after skipping it.
  return i + j >= b.length;
}

async function handleMusicCommand(argument) {
  const arg = (argument ?? "").trim();

  try {
    if (!arg || arg === "help") return postLocal(COMMAND_HELP);

    if (arg === "off") return game.settings.set(MODULE_ID, "enabled", false);
    if (arg === "on") return game.settings.set(MODULE_ID, "enabled", true);
    if (arg === "pause" || arg === "stop") return setPlaying(false);
    if (arg === "play" || arg === "resume") return setPlaying(true);
    if (arg === "diagnose" || arg === "debug") return showDiagnostics();

    if (arg === "sync") {
      if (!audio || audio.paused) {
        throw new MusicError("Nothing is playing for you right now.",
          "Type /music play first, or run /music diagnose.");
      }
      const lag = syncToLive({ force: true });
      return postLocal(`<p>Skipped ${lag.toFixed(1)}s of buffered delay.</p>`);
    }

    // "/music direction", "/music direction edit", "/music direction clear",
    // "/music direction keep it ambient". Setting by typing is deliberate:
    // one-line rules are most of them, and the editor is one word away for
    // the rest.
    const direction = arg.match(/^direction\b\s*([^]*)$/i);
    if (direction) {
      const rest = direction[1].trim();
      const current = guidance();

      if (!rest || /^(show|status)$/i.test(rest)) {
        return postLocal(current
          ? `<p><b>Music direction</b><br>${esc(current).replace(/\n/g, "<br>")}</p>`
            + (game.user.isGM
              ? `<p><i>/music direction edit</i> to change it.</p>` : "")
          : `<p>No music direction is set.`
            + (game.user.isGM
              ? ` Add one with <i>/music direction edit</i>, or type it: `
                + `<i>/music direction always keep the music ambient</i>.`
              : ` Only the GM can set one.`) + `</p>`);
      }
      if (/^(edit|manage|set|add|new)$/i.test(rest)) return openDirectionEditor();

      if (/^(clear|none|off|reset)$/i.test(rest)) {
        if (!current) return postLocal("<p>There was no music direction to clear.</p>");
        await setGuidance("");  // the setting's onChange pushes it to the server
        return postLocal("<p>Music direction cleared.</p>");
      }

      const kept = cleanGuidance(rest);
      if (!kept) {
        throw new MusicError("That direction is empty once trimmed.",
          "Write it as a plain sentence, like /music direction keep the music "
          + "ambient and in the background.");
      }
      await setGuidance(kept);
      return postLocal(`<p><b>Music direction set</b><br>${esc(kept)}</p>`
        + (current ? `<p><i>It replaced: ${esc(current)}</i></p>` : "")
        + `<p><i>It applies to the next /music prompt.</i></p>`);
    }

    // "/music preset tavern", "/music presets", "/music presets edit",
    // "/music preset save Ambush". Saving is namespaced under "preset" rather
    // than being its own verb because "/music save the village from the fire"
    // is a scene somebody will type, and it must stay a scene.
    const preset = arg.match(/^presets?\b\s*(.*)$/i);
    if (preset) {
      const rest = preset[1].trim();
      if (/^(edit|manage|add|new)$/i.test(rest)) return openPresetManager();

      const saving = rest.match(/^(?:save|keep)\b\s*(.*)$/i);
      if (saving) {
        const name = saving[1].trim();
        if (!name) {
          throw new MusicError("/music preset save needs a name.",
            "For example: /music preset save Ambush. It keeps whatever is "
            + "playing right now, knobs and all.");
        }
        await fetchStatus();
        const captured = normalizePreset({ ...liveAsPreset(), label: name });
        await savePresets([...getPresets(), captured]);
        updatePanel();
        return postLocal(`<p>Saved <b>${esc(captured.label)}</b> — `
          + `<i>${esc(captured.style)}</i></p>`);
      }

      const presets = getPresets();
      if (!presets.length) {
        throw new MusicError("No presets are configured.",
          game.user.isGM
            ? "Add some with /music presets edit, or from the sliders button in "
              + "the Music sidebar tab."
            : "Ask your GM to add some in the Music sidebar tab.");
      }
      if (!rest) {
        return postLocal(`<p>${presets.map(p =>
          `<b>${esc(p.label)}</b> — ${esc(p.style)}`
          + (p.raw ? "" : " <i>(rewritten)</i>")
          + (tuningSummary(p.tuning) ? ` <i>${esc(tuningSummary(p.tuning))}</i>` : "")
        ).join("<br>")}</p>`
          + (game.user.isGM ? `<p><i>/music presets edit</i> to change them.</p>` : ""));
      }
      const wanted = findPreset(rest);
      if (!wanted) {
        throw new MusicError(`There is no preset called "${rest}".`,
          `Try one of: ${presets.map(p => p.label).join(", ")}.`);
      }
      return applyPreset(wanted);
    }

    // "/music widget", "/music widget on|off". A bare word toggles, because
    // the reason to type it is that the thing is either there or it is not.
    const widgetArg = arg.match(/^widget\b\s*(.*)$/i);
    if (widgetArg) {
      const word = widgetArg[1].trim().toLowerCase();
      if (word && word !== "on" && word !== "off") {
        throw new MusicError(`"${widgetArg[1].trim()}" is not on or off.`,
          "Use /music widget to toggle it, or /music widget on|off.");
      }
      const wanted = word ? word === "on" : !setting("widget");
      await game.settings.set(MODULE_ID, "widget", wanted);
      return postLocal(`<p>The status widget is ${wanted ? "on" : "off"}`
        + (wanted ? " — drag it wherever you want it." : ".") + `</p>`);
    }

    if (arg === "status") {
      const data = await fetchStatus();
      return postLocal(
        `<p>🎵 <b>${esc(data.prompt)}</b><br><i>${data.listeners} listener(s), ` +
        `model ${esc(data.model)}, rewriter ${esc(data.llm ?? "off")}, ` +
        `cross-fade ${esc(data.morph)}s, generating at ${esc(data.gen)}× realtime, ` +
        `your delay ${liveLag().toFixed(1)}s</i></p>`);
    }

    // Subcommands are matched on the keyword alone and validate their own
    // argument. Folding the argument into the pattern would make "/music
    // volume loud" fall through and be sung at the table instead of refused.
    const volume = arg.match(/^vol(?:ume)?\b\s*(.*)$/i);
    if (volume) {
      const value = Number(volume[1]);
      if (!volume[1] || !Number.isFinite(value) || value < 0 || value > 1) {
        throw new MusicError(`"${volume[1] || "(nothing)"}" is not a volume.`,
          "Give a number between 0 and 1, like /music volume 0.4.");
      }
      await game.settings.set(MODULE_ID, "volume", value);
      return postLocal(`<p>Your music volume is now ${Math.round(value * 100)}%.</p>`);
    }

    // The tuning knobs all take one number and read back the same way.
    const knob = arg.match(/^(morph|temp|topk|cfg)\b\s*(.*)$/i);
    if (knob) {
      const key = knob[1].toLowerCase();
      const value = Number(knob[2]);
      if (!knob[2] || !Number.isFinite(value)) {
        throw new MusicError(`"${knob[2] || "(nothing)"}" is not a number.`,
          `${key} takes one number — try /music ${key} ${KNOB_EXAMPLES[key]}.`);
      }
      const data = await retune({ [key]: value });
      return postLocal(`<p>${esc(key)} is now ${esc(data.status?.[key] ?? value)}.</p>`);
    }

    const llm = arg.match(/^llm\b\s*(.*)$/i);
    if (llm) {
      const word = llm[1].toLowerCase();
      if (word !== "on" && word !== "off") {
        throw new MusicError(`"${llm[1] || "(nothing)"}" is not on or off.`,
          "Use /music llm on or /music llm off.");
      }
      const data = await retune({ llm: word === "on" });
      return postLocal(`<p>Prompt rewriting is ` +
        (data.status?.llm ? `on (${esc(data.status.llm)}).` :
          `off.${word === "on"
            ? " The music server has no LLM API key configured — put one in "
              + "its .env file and restart it." : ""}`) + `</p>`);
    }

    // A single word that is one typo away from a command is almost certainly
    // that command: "/music stauts" should not morph the soundtrack into
    // whatever "stauts" happens to embed as.
    const nearMiss = !/\s/.test(arg) && COMMANDS.find(c => isOneEditApart(arg.toLowerCase(), c));
    if (nearMiss) {
      throw new MusicError(`"${arg}" is not a /music command. Did you mean /music ${nearMiss}?`,
        `Type /music help for the list. To use "${arg}" as a music style `
        + `anyway, type /music raw ${arg}.`);
    }

    const raw = /^raw\b/i.test(arg);
    const text = raw ? arg.replace(/^raw\b\s*/i, "").trim() : arg;
    if (!text) {
      throw new MusicError("/music raw needs a style after it.",
        "For example: /music raw dark ambient, low strings.");
    }
    await steer(text, { raw });
  } catch (err) {
    const music = reportError(err, { notify: false, context: "chat command" });
    postLocal(`<p><b>${esc(music.message)}</b>` +
      (music.hint ? `<br><span style="opacity:.85">${esc(music.hint)}</span>` : "") +
      `</p>`);
  }
}

function postLocal(content) {
  return ChatMessage.create({
    content,
    speaker: { alias: "Music" },
    whisper: [game.user.id]
  });
}

/**
 * Reduce a chat message to plain text.
 *
 * Foundry's chat input is rich text, so what reaches the chatMessage hook is
 * HTML -- "/music they enter the dungeon" arrives as
 * "<p>/music they enter the dungeon</p>". Matching the raw string against a
 * /^\/music/ pattern therefore never fires, and the command falls through to
 * Foundry's "invalid command" error. This is the fix for that.
 */
function plainText(message) {
  const template = document.createElement("template");
  template.innerHTML = String(message ?? "");
  template.content.querySelectorAll("br").forEach(br => br.replaceWith("\n"));
  return template.content.textContent.trim();
}

const MUSIC_PATTERN = /^\/music\b\s*([^]*)$/i;

/* ----------------------------------------------------------------- hooks */

Hooks.once("init", () => {
  game.settings.register(MODULE_ID, "serverUrl", {
    name: "Music server URL",
    hint: "Where stream_player.py --serve is reachable from players' browsers. " +
          "Must use the same scheme as Foundry itself: an https Foundry page " +
          "cannot load an http stream.",
    scope: "world",
    config: true,
    type: String,
    default: `${window.location.protocol}//${window.location.hostname}:30001`,
    onChange: () => {
      busDisabled = false;
      notifiedErrors.clear();
      refreshPlaybackState();
      fetchStatus({ notify: true }).catch(() => { /* reported */ });
    }
  });

  game.settings.register(MODULE_ID, "serverToken", {
    name: "Music server token",
    hint: "Must match --serve-token on the machine running stream_player.py. " +
          "Required whenever that machine is reachable from the internet; " +
          "leave blank if it is not.",
    scope: "world",
    config: true,
    type: String,
    default: "",
    onChange: () => {
      notifiedErrors.clear();
      refreshPlaybackState();
      fetchStatus({ notify: true }).catch(() => { /* reported */ });
    }
  });

  game.settings.register(MODULE_ID, "steerPermission", {
    name: "Who can change the music",
    hint: "Everyone at the table, trusted players and up, or the GM alone.",
    scope: "world",
    config: true,
    type: String,
    choices: {
      everyone: "Everyone",
      trusted: "Trusted players and GMs",
      gm: "GMs only"
    },
    default: "everyone",
    onChange: () => updatePanel()
  });

  game.settings.register(MODULE_ID, "announceInChat", {
    name: "Announce music changes in chat",
    hint: "Post a public message showing the scene and the style it became. " +
          "Turn off for a quieter chat log; the music still changes.",
    scope: "world",
    config: true,
    type: Boolean,
    default: true
  });

  // Standing direction for the prompt rewriter: house rules about how this
  // table's music should sound, and what recurring names mean. Stored here and
  // applied on the music server, so both ends have to be kept in step -- see
  // sendPrompt(), which resends it, and diagnose(), which compares them.
  //
  // config:false because a one-line settings input is the wrong shape for
  // several rules; the menu below opens a proper editor.
  game.settings.register(MODULE_ID, "guidance", {
    scope: "world",
    config: false,
    type: String,
    default: "",
    onChange: () => {
      updatePanel();
      directionEditor?.refreshSaved?.();
      // Push it now rather than waiting for someone to describe a scene, so
      // the editor's "in force on the server" line tells the truth. Only the
      // GM does it: every client sees this change, and a table of eight would
      // otherwise send eight identical requests.
      if (!game.user.isGM) return;
      retune({ guidance: guidance() })
        .then(() => fetchStatus())
        .catch(err => reportError(err, { context: "music direction" }));
    }
  });

  game.settings.registerMenu(MODULE_ID, "musicDirection", {
    name: "Music direction",
    label: "Write the standing direction",
    hint: "House rules the AI follows every time it turns a scene into music: "
        + "how this table should sound in general (\"keep it ambient\"), and "
        + "what recurring names mean (\"The Town is a Spanish fishing village\").",
    icon: "fa-solid fa-feather-pointed",
    type: buildDirectionMenuClass(),
    restricted: true
  });

  // The presets themselves. Edited through the manager below rather than in
  // the settings form: a preset is a label, some words, a rewrite choice and
  // up to four knobs, and it is worth testing before it is kept.
  game.settings.register(MODULE_ID, "presetList", {
    scope: "world",
    config: false,
    type: Array,
    default: [],
    onChange: () => { updatePanel(); presetManager?.refreshLive?.(); }
  });

  // Set once the list above holds the truth; until then an empty list means
  // "not yet migrated" rather than "deliberately empty".
  game.settings.register(MODULE_ID, "presetsMigrated", {
    scope: "world",
    config: false,
    type: Boolean,
    default: false
  });

  // Pre-1.2 storage: "Label | style" lines. Read only until migratePresets()
  // has moved a world across, and kept afterwards so nothing is thrown away.
  game.settings.register(MODULE_ID, "presets", {
    scope: "world",
    config: false,
    type: String,
    default: LEGACY_DEFAULT_PRESETS,
    onChange: () => updatePanel()
  });

  game.settings.registerMenu(MODULE_ID, "presetManager", {
    name: "Preset buttons",
    label: "Add, test and adjust presets",
    hint: "The buttons in the Music sidebar tab: a label, the music it plays, " +
          "and optional generation settings. Each one can be tested from the " +
          "editor before it is saved.",
    icon: "fa-solid fa-sliders",
    type: buildPresetMenuClass(),
    restricted: true
  });

  // Table-wide transport state. World-scoped so a GM pressing stop stops the
  // music for the whole table, and so the state survives a reload.
  game.settings.register(MODULE_ID, "playback", {
    scope: "world",
    config: false,
    type: String,
    default: "playing",
    onChange: () => refreshPlaybackState()
  });

  game.settings.register(MODULE_ID, "enabled", {
    name: "Play the live music",
    hint: "Turn off to silence the stream for yourself only.",
    scope: "client",
    config: true,
    type: Boolean,
    default: true,
    onChange: () => refreshPlaybackState()
  });

  game.settings.register(MODULE_ID, "volume", {
    name: "Music volume",
    hint: "Your own level, on top of the global Music slider in the Playlists tab.",
    scope: "client",
    config: true,
    type: Number,
    range: { min: 0, max: 1, step: 0.05 },
    default: 0.5,
    onChange: () => applyVolume()
  });

  game.settings.register(MODULE_ID, "useMusicBus", {
    name: "Route through Foundry's Music channel",
    hint: "Makes the core Music volume slider control the stream. Needs the " +
          "music server to send CORS headers, which it does by default; the " +
          "module falls back to direct playback automatically if it cannot.",
    scope: "client",
    config: true,
    type: Boolean,
    default: true,
    onChange: () => { busDisabled = false; refreshPlaybackState(); }
  });

  // Off by default: the screen is already full, and the sidebar tab answers
  // the same question for anyone who has not asked for a second readout.
  game.settings.register(MODULE_ID, "widget", {
    name: "Show the on-screen status widget",
    hint: "A small draggable readout of what the music is doing — the same "
        + "information as /music status, without opening the Music tab. Drag "
        + "it anywhere; it stays where you leave it. Yours alone: turning it "
        + "on does not put it on anyone else's screen.",
    scope: "client",
    config: true,
    type: Boolean,
    default: false,
    // The panel's header button shows this state, so it is redrawn too rather
    // than waiting up to a poll interval to catch up with a press of itself.
    onChange: () => { refreshWidget(); updatePanel(); }
  });

  // Where this client left the widget, and whether it is folded down to the
  // one status line. Not in the settings form: it is set by dragging it.
  game.settings.register(MODULE_ID, "widgetPlacement", {
    scope: "client",
    config: false,
    type: Object,
    default: { left: null, top: null, collapsed: false },
    onChange: () => updateWidget()
  });

  game.settings.register(MODULE_ID, "autoSync", {
    name: "Keep up with the live edge",
    hint: "Periodically skip buffered audio so you hear changes as soon as " +
          "everyone else. Turn off if the skips are audible on your connection.",
    scope: "client",
    config: true,
    type: Boolean,
    default: true
  });

  // Foundry v14 parses chat commands from a registry. Registering here means
  // /music is a real command rather than something intercepted after the fact.
  const ChatLog = foundry.applications?.sidebar?.tabs?.ChatLog;
  if (ChatLog?.CHAT_COMMANDS) {
    ChatLog.CHAT_COMMANDS.music = {
      rgx: MUSIC_PATTERN,
      fn: (command, match) => {
        handleMusicCommand(plainText(match[1]));
        return false;  // don't post the raw "/music ..." text
      }
    };
  }
});

Hooks.once("ready", () => {
  game.socket.on(SOCKET, (data) => {
    if (data?.action === "sync") {
      startPlayback();     // no-op if already playing
      if (setting("autoSync")) syncToLive();
    }
  });

  refreshPlaybackState();
  refreshWidget();

  // Presets moved from a text setting to structured data in 1.2; carry an
  // existing world's list across before anything reads it.
  migratePresets().catch(err => log("preset migration skipped:", err?.message ?? err));

  // Foundry builds its audio buses on the first user gesture. If we started
  // before that happened we are playing direct, and the core Music slider is
  // being applied by hand -- so reconnect through the mixer once it exists.
  game.audio?.unlock?.then(() => {
    if (audio && !bus && !busDisabled && setting("useMusicBus")) {
      log("Foundry's audio mixer is up; reconnecting through the Music channel");
      startPlayback({ restart: true });
    }
  });

  // One deliberate check on load, so a session that is going to be silent says
  // why now rather than when someone first tries to use it. Players are only
  // told about things they can act on; the rest is the GM's to fix.
  fetchStatus({ notify: game.user.isGM }).catch(() => { /* reported */ });
  log("ready; streaming from", serverUrl() || "(no URL configured)");
});

// A window that shrinks must not take the widget off screen with it: the only
// way back would be to turn the setting off and on again.
window.addEventListener("resize", () => {
  if (!widget?.isConnected) return;
  const box = widget.getBoundingClientRect();
  const spot = clampWidget(box.left, box.top);
  if (spot.left !== box.left || spot.top !== box.top) placeWidget(spot.left, spot.top);
});

// Keep in step with the core Music slider when we are not routed through it.
Hooks.on("globalPlaylistVolumeChanged", () => { if (!bus) applyVolume(); });

// The Playlists tab is the "music" tab, so the transport belongs there.
Hooks.on("renderPlaylistDirectory", (app, element) => {
  // v13+ hands over an HTMLElement; v12 hands over a jQuery wrapper.
  injectPanel(element?.jquery ? element[0] : element);
});

// Pre-v14 Foundry has no command registry; intercept the message instead.
// In v14 this hook still runs first and handles the command, which is fine --
// the registry entry above is the fallback, not the other way round.
Hooks.on("chatMessage", (chatLog, message) => {
  const match = plainText(message).match(MUSIC_PATTERN);
  if (!match) return true;
  handleMusicCommand(match[1] ?? "");
  return false;  // stop Foundry from posting the raw "/music ..." text
});
